const input = $input.first()?.json || {};

const request = input.body && typeof input.body === 'object'
  ? input.body
  : input;

const clean = (v) => String(v ?? '').trim();

return [{
  json: {
    request_id: clean(request.request_id) || `REQ-${Date.now()}`,
    requester_name: clean(request.requester_name),
    requester_email: clean(request.requester_email),
    request_title: clean(request.request_title),
    objective: clean(request.objective),
    deliverables: clean(request.deliverables),
    due_date: clean(request.due_date),
    budget_status: clean(request.budget_status),
    required_systems: clean(request.required_systems),
    approvals_required: clean(request.approvals_required),
    business_impact: clean(request.business_impact),
    urgency: clean(request.urgency),
    data_sensitivity: clean(request.data_sensitivity),
    request_type_hint: clean(request.request_type_hint),
    request_source: input.body ? 'webhook' : 'manual',
    received_at: new Date().toISOString()
  }
}];

const j = $input.first().json || {};

const required = [
  'requester_name',
  'requester_email',
  'request_title',
  'objective',
  'deliverables',
  'due_date'
];

const missing = required.filter(k => !String(j[k] || '').trim());

const questions = [];
if (!j.objective) questions.push('What business outcome should this request achieve?');
if (!j.deliverables) questions.push('What specific outputs or deliverables are required?');
if (!j.due_date) questions.push('What is the required delivery date?');
if (!j.required_systems) questions.push('Which systems, tools or data sources are involved?');
if (!j.approvals_required) questions.push('Who needs to approve the work or final output?');
if (!j.budget_status) questions.push('Is budget or commercial approval already confirmed?');

return [{
  json: {
    ...j,
    brief_complete: missing.length === 0,
    missing_required_fields: missing,
    clarification_questions: questions
  }
}];

const j = $input.first().json || {};
const questions = Array.isArray(j.clarification_questions) ? j.clarification_questions : [];

return [{
  json: {
    ...j,
    triage_status: 'Information Required',
    next_action: 'Requester to provide missing information',
    action_owner: j.requester_name || 'Requester',
    clarification_message:
      `Thanks for the request. Before triage can continue, please confirm:\n\n` +
      questions.map((q, i) => `${i + 1}. ${q}`).join('\n')
  }
}];

