const input = $input.first().json || {};
const raw =
  input.output?.[0]?.content?.find(c => c.type === 'output_text')?.text ||
  input.output?.[0]?.content?.[0]?.text ||
  input.text ||
  '';

if (!raw) throw new Error('No classification output returned.');

const cleaned = String(raw).replace(/```json/gi,'').replace(/```/g,'').trim();
let parsed;
try { parsed = JSON.parse(cleaned); }
catch { throw new Error('Classification output was not valid JSON.'); }

const source = $('Check Brief Completeness').first().json;

return [{
  json: {
    ...source,
    request_type: parsed.request_type || 'Other',
    delivery_route: parsed.delivery_route || '',
    triage_summary: parsed.summary || '',
    ai_risks: Array.isArray(parsed.risks) ? parsed.risks : [],
    dependencies: Array.isArray(parsed.dependencies) ? parsed.dependencies : [],
    decisions_needed: Array.isArray(parsed.decision_needed) ? parsed.decision_needed : [],
    recommended_owner_type: parsed.recommended_owner_type || 'Delivery Lead',
    complexity: parsed.complexity || 'Medium'
  }
}];

const j = $input.first().json || {};

let score = 0;
const reasons = [];

const urgency = String(j.urgency || '').toLowerCase();
if (urgency === 'high') { score += 20; reasons.push('High urgency'); }
else if (urgency === 'medium') score += 10;

const impact = String(j.business_impact || '').toLowerCase();
if (impact === 'high') { score += 20; reasons.push('High business impact'); }
else if (impact === 'medium') score += 10;

const sensitivity = String(j.data_sensitivity || '').toLowerCase();
if (sensitivity.includes('sensitive') || sensitivity.includes('confidential')) {
  score += 20; reasons.push('Sensitive data involved');
} else if (sensitivity.includes('internal')) {
  score += 5;
}

if (String(j.budget_status || '').toLowerCase().includes('unknown')) {
  score += 10; reasons.push('Budget not confirmed');
}

if ((j.ai_risks || []).length >= 3) {
  score += 10; reasons.push('Multiple delivery risks identified');
}

const complexity = String(j.complexity || '').toLowerCase();
if (complexity === 'high') { score += 15; reasons.push('High complexity'); }
else if (complexity === 'medium') score += 5;

if (String(j.approvals_required || '').trim()) {
  score += 5;
}

score = Math.min(score, 100);

const cfg = $('Set Request Triage Config').first().json || {};
const high = Number(cfg.high_risk_threshold || 70);
const approval = Number(cfg.approval_required_threshold || 45);

let route;
if (score >= high) route = 'High Risk Review';
else if (score >= approval) route = 'Approval Required';
else route = 'Standard Triage';

return [{
  json: {
    ...j,
    triage_score: score,
    triage_risk_level: score >= high ? 'High' : score >= approval ? 'Medium' : 'Low',
    triage_route: route,
    score_reasons: reasons
  }
}];

const j = $input.first().json || {};
return [{
  json: {
    ...j,
    triage_status: 'Approval Required',
    approval_status: 'Pending',
    next_action: 'Await human approval',
    approval_reason:
      `Triage score ${j.triage_score}/100 (${j.triage_risk_level}). Route: ${j.triage_route}.`,
    approval_message:
      `Approval required for ${j.request_title}\n\n` +
      `Request ID: ${j.request_id}\n` +
      `Summary: ${j.triage_summary}\n` +
      `Risk: ${j.triage_risk_level} (${j.triage_score}/100)\n` +
      `Due: ${j.due_date}\n` +
      `Budget: ${j.budget_status}\n` +
      `Recommended owner: ${j.recommended_owner_type}\n\n` +
      `POST the decision to /webhook/project-request-approval with request_id, decision and approver_name.`
  }
}];

const j = $input.first().json || {};
return [{
