const j = $input.first().json || {};
return [{
  json: {
    ...j,
    triage_status: 'Closed / Declined',
    next_action: 'Review rejection reason before resubmitting',
    rejection_reason: 'Approval was not granted.'
  }
}];

const data = $input.first().json || {};
const records = Array.isArray(data.records) ? data.records : [];

const rows = records.map(r => ({ id: r.id, ...(r.fields || {}) }));

const counts = rows.reduce((acc, r) => {
  const status = String(r.Status || 'Unknown');
  acc[status] = (acc[status] || 0) + 1;
  return acc;
}, {});

const blocked = rows.filter(r =>
  /information required|on hold|approval/i.test(String(r.Status || ''))
);

const noOwner = rows.filter(r => !String(r.Assigned_Owner || '').trim());

return [{
  json: {
    total_open: rows.length,
    status_counts: counts,
    blocked_count: blocked.length,
    unassigned_count: noOwner.length,
    blocked_requests: blocked.slice(0, 10),
    unassigned_requests: noOwner.slice(0, 10),
    generated_at: new Date().toISOString(),
    markdown_summary: [
      '# Weekly Project Triage Summary',
      '',
      `Open requests: ${rows.length}`,
      `Blocked / awaiting action: ${blocked.length}`,
      `Unassigned: ${noOwner.length}`,
      '',
      '## Status counts',
      ...Object.entries(counts).map(([k,v]) => `- ${k}: ${v}`),
      '',
      '## Blocked / awaiting action',
      ...(blocked.length ? blocked.slice(0,10).map(r => `- ${r.Request_ID || ''} — ${r.Request_Title || 'Untitled'} — ${r.Status || ''}`) : ['- None'])
    ].join('\n')
  }
}];

const input = $input.first()?.json || {};
const body = input.body && typeof input.body === 'object' ? input.body : input;
const request_id = String(body.request_id || '').trim();
const decision = String(body.decision || '').trim().toUpperCase();
const approver_name = String(body.approver_name || '').trim();

if (!request_id) throw new Error('request_id is required.');
if (!['APPROVED','REJECTED','CHANGES_REQUESTED'].includes(decision)) {
  throw new Error('decision must be APPROVED, REJECTED or CHANGES_REQUESTED.');
}

return [{ json: {
  request_id,
  approval_decision: decision,
  approver_name,
  approval_received_at: new Date().toISOString()
}}];

const lookup = $input.first()?.json || {};
const decision = $('Normalise Approval Decision').first().json || {};
const record = Array.isArray(lookup.records) ? lookup.records[0] : null;
if (!record?.id) throw new Error('No Airtable triage record found for request_id.');

const existing = record.fields || {};
const approved = decision.approval_decision === 'APPROVED';
const rejected = decision.approval_decision === 'REJECTED';

let status = 'Approval Required';
let nextAction = 'Reviewer requested changes before approval';
if (approved) {
  status = 'Assigned / In Progress';
  nextAction = 'Schedule delivery kick-off and confirm scope, dependencies and milestones';
} else if (rejected) {
  status = 'Closed / Declined';
  nextAction = 'Review rejection reason before resubmitting';
}

return [{ json: {
  ...existing,
  airtable_record_id: record.id,
  request_id: decision.request_id,
  approval_decision: decision.approval_decision,
  approver_name: decision.approver_name,
  approval_received_at: decision.approval_received_at,
  triage_status: status,
  next_action: nextAction,
  assigned_owner: approved ? (existing.Assigned_Owner || existing.Recommended_Owner || 'Delivery Lead') : ''
}}];

